Global CDN & AWS WAF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Global CDN & AWS WAF container

Container_Boundary(global_cdn_waf, "Global CDN & AWS WAF") {
    Component(Amazon_CloudFront, "Amazon CloudFront", "AWS CloudFront", "Provides global content delivery and edge caching for the e-commerce platform.")
    Component(AWS_WAF, "AWS WAF", "AWS WAF with Bot Control", "Inspects and filters incoming web traffic to protect against common web exploits and bots.")
}

Rel(Amazon_CloudFront, AWS_WAF, "Routes incoming requests for security inspection", "HTTPS")

@enduml

Application Load Balancer (ALB).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(alb, "Application Load Balancer (ALB)") {
    Component(tls_engine, "TLS Termination & Routing Engine", "AWS ALB", "Handles TLS termination using AWS ACM (TLS 1.3), performs header-based routing, and manages traffic flow.")
    Component(auth_offloader, "Authentication Offloader", "Amazon Cognito Integration", "Offloads JWT validation and handles OIDC/OAuth 2.0 identity verification.")
    Component(header_injector, "Header Injector", "ALB Native Middleware", "Forwards validated identity claims via injected headers such as X-User-ID and X-User-Roles to backend services.")
}

Rel(tls_engine, auth_offloader, "Delegates token validation", "OIDC/OAuth 2.0")
Rel(auth_offloader, header_injector, "Passes validated claims", "Internal")

@enduml

Amazon Cognito.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon Cognito container

Container_Boundary(amazon_cognito, "Amazon Cognito") {
    Component(User_Pool_Manager, "User Pool Manager", "Amazon Cognito User Pools", "Manages user identities, directories, and profiles for book buyers and site administrators.")
    Component(Federation_and_Identity_Provider, "Federation and Identity Provider", "OIDC / SAML / OAuth 2.0", "Handles federated identity and social logins to support cross-region availability.")
    Component(Adaptive_MFA_Handler, "Adaptive MFA Handler", "Amazon Cognito Advanced Security", "Provides adaptive multi-factor authentication to secure user sessions.")
}

Rel(Federation_and_Identity_Provider, User_Pool_Manager, "Authenticates users and maps tokens to", "")
Rel(User_Pool_Manager, Adaptive_MFA_Handler, "Triggers security challenges via", "")

@enduml

